            make_q("In DBSCAN, what defines a 'Core Point'?", ["A point with the largest target value", "A point that has at least `min_samples` data points (including itself) within its $\\epsilon$-radius neighborhood", "A point located at the origin (0, 0)", "The center of mass of the dataset"], 1, "A core point contains at least `min_samples` observations within its $\\epsilon$-neighborhood: $|N_\\epsilon(p)| \\ge \\text{min\\_samples}$."),
            make_q("In DBSCAN, what defines a 'Border Point'?", ["A point with zero neighbors", "A point that has fewer than `min_samples` within its $\\epsilon$-radius, but falls within the $\\epsilon$-neighborhood of a Core Point", "A point with negative coordinates", "A point on the outer edge of the CSV file"], 1, "Border points lack sufficient density themselves, but are reachable within $\\epsilon$ of an established Core Point."),
            make_q("In DBSCAN, how are Noise Points (Outliers) labeled by Scikit-learn?", ["`label = 0`", "`label = -1`", "`label = 999`", "`label = NaN`"], 1, "Scikit-learn assigns label `-1` to any sample that is neither a core point nor reachable from any core point (noise/outlier)."),
            make_q("What is a major advantage of DBSCAN over K-Means?", ["DBSCAN runs in $O(1)$ time", "DBSCAN does not require specifying the number of clusters $K$ in advance and can discover arbitrary non-linear geometric shapes", "DBSCAN requires no parameters", "DBSCAN always produces spherical clusters"], 1, "DBSCAN discovers natural cluster counts organically and traces arbitrary non-linear shapes (circles, manifolds, roads)."),
