            make_q("Why is feature scaling mandatory before running DBSCAN?", ["Because DBSCAN requires scaled features to run in Python", "Because neighborhood search uses distance metrics (Euclidean); unscaled features with large numerical ranges distort spherical neighborhoods into needles", "Because DBSCAN converts features to probabilities", "Because scaling eliminates noise points"], 1, "An $\\epsilon$-radius hypersphere requires uniform coordinate scaling; unscaled features cause search balls to distort along the largest axis."),
            make_q("What is the time complexity of DBSCAN with spatial indexing (e.g. KD-Tree or Ball Tree) in low dimensions?", ["$O(N^2)$", "$O(N \\log N)$", "$O(N^3)$", "$O(1)$"], 1, "Spatial indexing trees reduce neighborhood range queries to $O(\\log N)$, yielding an overall complexity of $O(N \\log N)$."),
            make_q("What is the worst-case time complexity of DBSCAN without spatial indexing (or in very high dimensions)?", ["$O(N \\log N)$", "$O(N^2)$ due to computing all pairwise distances", "$O(N!)$", "$O(D)$"], 1, "Without indexing (or when high dimensionality forces brute-force distance scans), DBSCAN evaluates $O(N^2)$ pairwise queries."),
            make_q("What is the difference between Agglomerative and Divisive hierarchical clustering?", ["Agglomerative is bottom-up (merges points); Divisive is top-down (recursively splits the root cluster)", "Agglomerative is supervised; Divisive is unsupervised", "Agglomerative is for text; Divisive is for images", "They are identical algorithms"], 0, "Agglomerative begins with $N$ individual clusters and merges upward; Divisive starts with 1 giant cluster and splits downward."),
            make_q("What is Cophenetic Correlation in hierarchical clustering?", ["The correlation between two features in pandas", "A measure of how faithfully a dendrogram preserves the original pairwise distances between data points", "The ratio of noise points to core points", "The execution time of the dendrogram"], 1, "The cophenetic correlation coefficient quantifies how closely dendrogram branch merge heights reflect original point distances."),
            make_q("In DBSCAN, can a Border Point belong to more than one cluster?", ["No, border points cannot belong to any cluster", "Yes, if a point is within $\\epsilon$ of core points from two different clusters, its assignment depends on which cluster processes it first", "Border points are always labeled -1", "Border points only exist in K-Means"], 1, "Border points equidistant between two clusters can be non-deterministically assigned depending on sample evaluation order."),
            make_q("Is Core Point classification deterministic in DBSCAN?", ["No, it changes every run", "Yes, core point qualification is strictly deterministic because it depends only on sample counts within a fixed $\\epsilon$ radius", "Only if random seed is set", "Only on GPUs"], 1, "Core point identification is 100% deterministic: a sample either has $\\ge \\text{min\\_samples}$ in its neighborhood or it does not."),
            make_q("What is an empirical heuristic for choosing `min_samples` in DBSCAN for a dataset with $D$ features?", ["`min_samples = 1`", "`min_samples >= 2 * D` (or at least 3-5 in 2D)", "`min_samples = N / 2`", "`min_samples = 100`"], 1, "A standard heuristic established by Ester et al. is setting $\\text{min\\_samples} \\ge 2 \\times D$, with $\\ge 3$ minimum in low dimensions."),
            make_q("What happens in DBSCAN if `min_samples = 1`?", ["The algorithm crashes", "Every point becomes a core point, and the algorithm degrades to single-linkage hierarchical clustering with zero noise points", "All points become noise (-1)", "The algorithm creates only 1 cluster"], 1, "With `min_samples=1`, every point is its own core point, merging all points within $\\epsilon$ into single-linkage chains with zero noise."),
