            make_q("What is the reconstruction error (reconstruction loss) in PCA?", ["The number of NaN values", "The squared Euclidean distance between the original data points and their lower-dimensional PCA reconstructed approximations: $\\|X - \\hat{X}\\|_F^2$", "The time required to run SVD", "The difference between eigenvalues"], 1, "Reconstruction error measures the information lost by discarding the trailing $d - k$ principal components."),
            make_q("Is PCA a supervised or unsupervised dimensionality reduction technique?", ["Supervised, because it uses target labels $y$", "Unsupervised, because it operates strictly on the feature matrix $X$ without knowledge of target labels $y$", "Semi-supervised", "Reinforcement learning"], 1, "PCA is entirely unsupervised; it maximizes variance among inputs $X$ with zero awareness of target classes or outcomes."),
