            make_q("What is the correlation between $PC_1$ and $PC_2$ in any standard PCA transformation?", ["$r = 1.0$", "$r = 0.0$ (they are mathematically uncorrelated)", "$r = -1.0$", "It depends on the dataset"], 1, "Because principal component directions are orthogonal eigenvectors, the covariance and correlation between any two components is strictly zero."),
