            make_q("What is the maximum number of principal components that can be extracted from a dataset with $N$ samples and $D$ features?", ["$N \\times D$", "$\\min(N - 1, D)$", "$D^2$", "Infinite"], 1, "The maximum rank of centered matrix $X$ is $\\min(N-1, D)$, bounding the maximum number of non-zero eigenvalues."),
            make_q("If you have 1,000 features but only 50 samples, what is the maximum number of informative principal components PCA can extract?", ["1,000", "49 ($N - 1$)", "50", "2"], 1, "Centering 50 samples yields at most 49 linearly independent dimensions; components beyond 49 have eigenvalues of exactly zero."),
